    ["40392"] = {
    ["Title"]="[DEPRECATED] Summons by the Ranger-General",
    ["Description"]="Greetings YOUR_NAME, I have received word from Alah'thalas that the Ranger-General requests your presence, please make your way to her as soon as possible.",
    ["Objectives"]="Travel to Alah'thalas and speak to Ranger-General Damilara Sunsorrow.",
