    -- Betina Bigglezink
    -- Betina Bigglezink -> Betina Bigglezink (MobNpcData.lua)
    -- Scholomance -> Scholomance (ZoneData.lua)
    ["5531"] = {
    ["Title"]="Betina Bigglezink",
    ["Description"]="Getirdiğin yumurtalar Afet'in vebalı bir ejderha sürüsü yaratma deneylerinde kullanılacaktı. Bu donmuş siyah ejderha yumurtaları çalışmalarında paha biçilmez olacaktı ve takvimlerini kesinlikle hızlandıracaktı.\n\nŞimdi, araştırmalarına son verme zamanımız geldi.\n\nDonmuş yumurtaları dışarıdaki Betina Bigglezink'e götür. Bilim ve simyada son derece bilgilidir ve Afet'e karşı kullanabileceğimiz bir silah üretti. Yardımınızla onlara ağır bir darbe indireceğiz.",
    ["Objectives"]="Donmuş Yumurtaları Betina Bigglezink'e getir.",
    ["Progress"]="Merhaba, YOUR_NAME! Birkaç ejderha yumurtasıyla burada olduğunu duydum? Pekala, görelim bakalım!",
    ["Completion"]="İşte buradalar! Hem de ne güzel bir kapta. Mükemmel boyutta!\n\nBu yumurtaları güvenli bir yerde tutacağız ki daha sonra inceleyebilelim, ama şu anda onları getirdiğin şeye ihtiyacımız var.\n\nÇok özel bir kullanımı olan bir cihaz yarattım: Scholomance'ın ölümsüz bilginlerini yok etmek. Vebalı bir ejderha sürüsü yaratma çabalarında ejderhaları inceliyorlar ve onların ilerlemesini durdurmalıyız.\n\nCihaza Şafak Hamlesi diyorum, çünkü... işe yarayıp yaramadığından emin değilim!\n\nBizim için öğrenir misin?",
    ["minlevel"]="57",
    ["questlevel"]="60",
    }, -- end Betina Bigglezink

    -- Scholomance
    -- Alchemist Arbington -> Simyacı Arbington (MobNpcData.lua)
    -- Caer Darrow -> Caer Darrow (ZoneData.lua)
    -- Scholomance -> Scholomance (ZoneData.lua)
    -- Chillwind Point -> Serinrüzgar Noktası (ZoneData.lua)
    -- Western Plaguelands -> Batı Veba Toprakları (ZoneData.lua)
    ["5533"] = {
    ["Title"]="Scholomance",
    ["Description"]="Caer Darrow adasında Scholomance yatar - Afet nekromansisinin ve kötülüğünün sefil bir merkezi. Düşmanımız içeride ikamet ediyor, habersiz kurbanlar üzerinde anlatılamaz ahlaksızlık eylemleri yürütüyor... en azından öyle tahmin ediyoruz. Bir kapı yolu tıkıyor ve ne kadar denersek deneyelim uygun bir anahtar olmadan giriş sağlanamıyor.\n\nSimyacı Arbington Scholomance konusunda son derece bilgilidir ve bir anahtarın nasıl elde edileceği konusunda bir fikre sahiptir. Bana değerini kanıtladın ve şimdi bu görevi sana emanet ediyorum. Bu konuda onunla konuş.",
    ["Objectives"]="Batı Veba Toprakları'ndaki Serinrüzgar Noktası'nda bulunan Simyacı Arbington ile konuş.",
    ["Progress"]="",
    ["Completion"]="İyi karşılaştık, YOUR_CLASS. Son çalışmalarımın adil bir kısmını Scholomance'a adadım ve bir anahtarı edinmenin bir yolunu bildiğime inanıyorum... ön kapıyı geçmeni sağlayacak bir anahtar.\n\nİçeride ne korkunç manzaraların görülebileceğini ancak hayal edebiliyorum, YOUR_NAME. Sizin gibi kahraman tiplerin bunu bazen nasıl yaptığını bilmiyorum...",
    ["minlevel"]="55",
    ["questlevel"]="55",
    }, -- end Scholomance

    -- Kim'jael's "Missing" Equipment
    -- Magus Rimtori -> Büyücü Rimtori (MobNpcData.lua)
    -- Kim'jael -> Kim'jael (MobNpcData.lua)
    -- Ruins of Eldarath -> Eldarath Harabeleri (ZoneData.lua)
    -- Azshara -> Azshara (ZoneData.lua)
    ["5534"] = {
    ["Title"]="Kim'jael'in 'Kayıp' Ekipmanı",
    ["Description"]="Ne?! Ne?!\n\nBu senin için yeterince iyi değil miydi? Bu patlayıcıların ne kadar pahalı olduğunu biliyor musun? Satış fiyatları... oh, neyse. Pekala, biraz gerçek para kazanmak ister misin? Çünkü işler böyle yürür: Değerli bir çalışan olduğunu kanıtlar ve biraz dişini sıktıktan sonra yeterince ödüllendirilirsin.\n\n'Değerli' bir çalışansan, Eldarath Harabeleri'ne git ve Kan elflerinin aradığı o rünü bul. Naga görünüşe göre ona sahip.",
    ["Objectives"]="Eldarath Harabeleri'nde naganın elinde bulunan Bazı Rünleri bul ve Azshara'daki Kim'jael'e geri getir.",
    ["Progress"]="Eee, YOUR_NAME? Rün nerede? Sen iyi bir çalışansın, değil mi? Yardım etmek için buradasın?\n\nSana anlaştığımız şeyi ödeme konusunda beni iki kez düşündürme. Ne? Oh, hiçbir konuda anlaşmadık mı? Oh, harika... o zaman acele etme--sadece uzun sürerse çok daha az olacağını bil.",
    ["Completion"]="Haha! Harika!\n\nBunun ne için olduğunu ve beni kiralayan inek olan Büyücü Rimtori'nin bunu neden istediğini kesinlikle öğreneceğim. Hah! Şimdi sizi yakaladım, pislik Kan elfleri! Kim'jael! Ha! Onlara farelerin kim olduğunu öğreteceğim!\n\nİyi iş çıkardın, YOUR_NAME. Çok teşekkürler. Al, bu sikkeyi al ve git--çözmem gereken şeyler var.",
    ["minlevel"]="47",
    ["questlevel"]="53",
    }, -- end Kim'jael's "Missing" Equipment

    -- Spiritual Unrest
    -- Loh'atu -> Loh'atu (MobNpcData.lua)
    -- Azeroth -> Azeroth (ZoneData.lua)
    -- Shadowsong Shrine -> Gölgewarkı Tapınağı
    -- Azshara -> Azshara (ZoneData.lua)
    ["5535"] = {
    ["Title"]="Ruhani Huzursuzluk",
    ["Description"]="Çok uzun zaman önce, Soylular Gece elflerinin yetiştirdiği gizemli sanatların en güçlü öğrencilerinden bazılarıydı. Bu tür çalışmalarla birlikte gelen yozlaşma Gece elfi toplumuna büyük zarar verdi ve tüm Azeroth'u derinden etkiledi... eminim çok iyi biliyorsundur.\n\nNöbetçilere ruhları buldukça ölümlü bağlarından kurtaracağıma dair söz verdim. Sen de aynısını yaparsan seni ödüllendirebileceğime eminim.\n\nRuhlar buranın kuzeydoğusundaki Gölgewarkı Tapınağı'nda dolaşıyor.",
    ["Objectives"]="6 Soylu Hortlağı ve 6 Soylu Lichciği yok et, ardından Azshara'daki Loh'atu'ya dön.",
    ["Progress"]="Soylu ruhlarını araman nasıl gidiyor, YOUR_CLASS?\n\nBirçok olay Azeroth'un tüm ırklarına büyük acılar çektirdi, ancak belirsiz bir nedenle bu ruhlar tüm insanlar için bir veba gibi görünüyor. Belki de gizemli büyüye karşı devam eden arzularıdır--böyle bir arzu Yanan Lejyon'un habercisidir ve bunun nereye varabileceğini biliyoruz.",
    ["Completion"]="Aferin, YOUR_CLASS. Yardımınız için teşekkür ederiz. Ruhlar huzur içinde ve gizemli büyü arzularının çektiği tehditler azaldı.\n\nAzeroth'u kasıp kavuran çatışmanın her iki tarafının da senin bu tür şeylerin üzerinde olduğunu göreceğinden eminim.",
    ["minlevel"]="45",
    ["questlevel"]="47",
    }, -- end Spiritual Unrest

    -- A Land Filled with Hatred
    -- Cenarius -> Cenarius (MobNpcData.lua)
    -- Loh'atu -> Loh'atu (MobNpcData.lua)
    -- Ashenvale -> Ashenvale (ZoneData.lua)
    ["5536"] = {
    ["Title"]="Nefretle Dolu Bir Diyar",
    ["Description"]="Gece elflerinin şekilsiz, kötü bir yönü olan satir, bir zamanlar Cenarius'un dolaştığı kutsal toprakları enfekte ediyor. O iblis yaratıkların işlediği tüm vahşet söz konusu olduğunda Gece elfleri adına konuşamam, ancak elflere toprağı böyle bir beladan kurtarmada yardım etmek için Toprakana'ya yemin ettim.\n\nOnları temizlememde bana yardım edersen kendini kanıtlayacağından eminim.\n\nBuranın kuzeydoğusunda Haldarr klanını bulabilirsin. Güçlerine karşı kendini test ettikten sonra bana dön.",
    ["Objectives"]="6 Haldarr Satiri, 2 Haldarr Hilekarı, 2 Haldarr İblisadanmışı öldür ve ardından Ashenvale sınırındaki Loh'atu'ya dön.",
    ["Progress"]="Satirlere karşı savaşın nasıl gidiyor, YOUR_CLASS?\n\nDüşündüğün kadar güçlüler mi? Daha mı güçlüler? Yoksa senin kendi gücün karşısında bir hiç miydiler?",
    ["Completion"]="Aferin, YOUR_CLASS. Sadece yetenekli değil, aynı zamanda kurnaz olduğunu da görüyorum. Böyle yaratıkları yenmek, onu kendi ilahın olarak tanımasan bile Toprakana'nın ilkelerine olan sadakatinin bir kanıtıdır. O, bu gezegendeki ve ötesindeki her şeyin içindedir. Biri karanlık diğeri aydınlık olan gözleri gökyüzünde dolaşır, her zaman bize bakar.\n\nYaptığın şeyin takdiri olarak lütfen bu küçük miktardaki parayı al.",
    ["minlevel"]="45",
    ["questlevel"]="47",
    }, -- end A Land Filled with Hatred

