    -- Irondeep Supplies
    -- Dun Baldar -> Dun Baldar (ZoneData.lua)
    -- Irondeep -> Demirderinlik
    ["5892"] = {
    ["Title"]="Demirderinlik Malzemeleri",
    ["Description"]="Savaş başlamadan önce Dun Baldar için erzakları Demirderinlik madeninde sakladık. Orada su yüzüne çıkan trogglar, madeni koruyacak yedek birliklerimiz varken pek sorun teşkil etmiyordu, ancak şimdi Horde ile savaştığımız için Demirderinlik'in kontrolünü sağlayamıyoruz.\n\nDemirderinlik'teki malzemelere ihtiyacımız var, YOUR_NAME. Madene gir ve bana onlardan bir yük getir.",
    ["Objectives"]="Dun Baldar'daki İttifak Levazım Subayı'na 10 Demirderinlik Malzemesi getir.",
    ["Progress"]="Malzemeler yanında mı, YOUR_NAME? Asla yeterince sahip olamayız!",
    ["Completion"]="Aferin! Bu malzemeleri iyi değerlendireceğim! Teşekkürler, YOUR_NAME!",
    ["minlevel"]="51",
    ["questlevel"]="55",
    }, -- end Irondeep Supplies

    -- Coldtooth Supplies
    -- Frostwolf Keep -> Buzkurdu Kalesi (ZoneData.lua)
    -- Coldtooth -> Soğukdiş
    -- Stormpikes -> Fırtınamızrakları
    ["5893"] = {
    ["Title"]="Soğukdiş Malzemeleri",
    ["Description"]="Kuzeydeki Soğukdiş madeni bir zamanlar ekstra erzak depolamak için ideal bir yerdi, ancak şimdi Fırtınamızrakları ile savaş şiddetlendiği için madende konuşlanacak ve onu koruyacak yedek savaşçılara her zaman sahip olamıyoruz. Ve böylece madenin kontrolü genellikle İttifak'ın veya yeraltı sakinlerinin eline geçiyor...\n\nAma yine de malzemelerimize ihtiyacımız var, YOUR_NAME! Soğukdiş madenine git ve bana onlardan bir yük getir. Ve giderken düşmanlara karşı dikkatli ol; o yerde savaşın seyri hızla değişir...",
    ["Objectives"]="Buzkurdu Kalesi'ndeki Horde Levazım Subayı'na 10 Soğukdiş Malzemesi getir.",
    ["Progress"]="Soğukdiş madenine gittin mi, YOUR_NAME? İstediğim malzemeler yanında mı?",
    ["Completion"]="Ah, onları aldın. İyi iş, YOUR_NAME! Bu malzemeler o karanlık madende bu kadar uzun süre oturmaktan biraz küflenmiş ama yine de onları değerlendireceğiz.\n\nTeşekkür ederim, YOUR_NAME. Eylemlerin savaşan kuvvetlerimizin sürdürülmesi için hayati önem taşıyor.",
    ["minlevel"]="51",
    ["questlevel"]="55",
    }, -- end Coldtooth Supplies

    -- A Plague Upon Thee
    -- Nathaniel Dumah -> Nathaniel Dumah (MobNpcData.lua)
    -- Stratholme -> Stratholme (ZoneData.lua)
    -- Plaguewood -> Vebaormanı (ZoneData.lua)
    -- Eastern Plaguelands -> Doğu Veba Toprakları (ZoneData.lua)
    -- Chillwind Camp -> Serinrüzgar Karakolu (ZoneData.lua)
    -- Western Plaguelands -> Batı Veba Toprakları (ZoneData.lua)
    ["5903"] = {
    ["Title"]="Üzerinize Bir Veba",
    ["Description"]="Kızıl Haçlı Seferi'ni sadece kaba kuvvetle püskürtmeyi defalarca denedim ama bir sonuç alamadım. Alternatif olarak hayatlarını daha da zorlaştırmaya karar verdim.\n\nYardım etmeye razıysan, o bıçkı hanesini şimdiye kadar bulunmuş en korkunç termit türüyle istila etmek istiyorum.\n\nVebaormanı'nda, bir zamanlar yüce olan Stratholme yakınlarında, vebadan ve Afet'ten bir arada sağ çıkan bir tür var. Höyüklerini bul ve bu kavanozu onlarla doldur, böylece onları Haçlı Seferi üzerine salmaya hazırlayabilelim.",
    ["Objectives"]="Doğu Veba Toprakları'ndaki Termit Höyükleri üzerinde Boş Termit Kavanozu'nu kullan. 100 Veba Toprakları Termiti topladıktan sonra Batı Veba Toprakları'ndaki Serinrüzgar Karakolu'nda bulunan Nathaniel Dumah'a dön.",
    ["Progress"]="Termit höyüklerini buldun mu, YOUR_NAME? Vebaormanı'nın her yerinde olduklarını duydum.",
    ["Completion"]="Bunlar işe yarayacak, YOUR_NAME. Teşekkür ederim. Şunlara bir bak... Hepsi birbirine sokulmuş kaç taneler. Haçlı Seferi için neredeyse üzülüyorum ama yine de alacakları bıçkı hanesi asla onların değildi, öyle değil mi?",
    ["minlevel"]="48",
    ["questlevel"]="55",
    }, -- end A Plague Upon Thee

    -- A Plague Upon Thee
    -- Northridge Lumber Mill -> Northridge Bıçkı Hanesi
    -- Hearthglen -> Hearthglen (ZoneData.lua)
    -- Western Plaguelands -> Batı Veba Toprakları (ZoneData.lua)
    ["5904"] = {
    ["Title"]="Üzerinize Bir Veba",
    ["Description"]="Termitlere sahip olduğumuza göre, bu çelik takviyeli fıçıyı Hearthglen'in güneyindeki Northridge Bıçkı Hanesi'ne götür--onu kasabaya çıkan yolun batısında bulacaksın.\n\nOraya vardığında fıçıyı bıçkı hanesinin merkezine yerleştir; bir sandığın üzeri gibi uygun bir yer bul ve ardından aç. Termitler işlerini oradan yapmalı ve bıçkı hanesini Haçlı Seferi için kullanılamaz hale getirmelidir.",
    ["Objectives"]="Veba Toprakları Termit Fıçısı'nı yerleştirmek için Batı Veba Toprakları'ndaki Northridge Bıçkı Hanesi'nin merkezinde uygun bir yer bul.",
    ["Progress"]="",
    ["Completion"]="Fıçıyı sandığın üzerine koyduğunda termitlerin huzursuzlandığı açıkça görülüyor.",
    ["minlevel"]="48",
    ["questlevel"]="55",
    }, -- end A Plague Upon Thee

    -- Return to Chromie
    -- Carlin -> Carlin (MobNpcData.lua)
    -- Chromie -> Chromie (MobNpcData.lua)
    -- Joseph Redpath -> Joseph Kızıl-Yol (MobNpcData.lua)
    -- Darrowshire -> Darrowshire (ZoneData.lua)
    -- Andorhal -> Andorhal (ZoneData.lua)
    ["5941"] = {
    ["Title"]="Chromie'ye Dönüş",
    ["Description"]="Darrowshire Savaşı'nın birçok kutsal emanetini topladın. Her daha fazlasıyla döndüğünde kalbim köyüm için sızladı... onu kaderinden korumak için sızladı.\n\nBunun olamayacağını biliyorum ama Andorhal'daki o garip gnom Chromie bunun mümkün olduğunu söylüyor. Darrowshire'ı kurtarabileceğini söylüyor!\n\nEmanetleri toplamamı ve onları kendisine getirmeni istedi. Andorhal'ın yıkık hanında seni beklediğini söyledi.",
    ["Objectives"]="Kutsal Emanet Paketi'ni Andorhal'daki Chromie'ye götür.",
    ["Progress"]="Arkadaşın Carlin ile temas halindeydim. Köyünün felaketi için büyük acı çekiyor ama senden övgüyle bahsediyor ve işleri düzeltebileceğini biliyor.\n\nOh, ama eldeki konudan uzaklaşıyorum... YOUR_NAME, istediğim emanetler yanında mı?",
    ["Completion"]="Ah evet, işte oradalar. Birlikte güçlü bir büyü dokuyorlar, Darrowshire ruhlarını yükseltecek bir büyü.\n\nO büyüyle ve biraz da şansla Joseph Kızıl-Yol'u kurtarabiliriz!",
    ["minlevel"]="50",
    ["questlevel"]="60",
    }, -- end Return to Chromie

    -- Hidden Treasures
    ["5942"] = {
    ["Title"]="Gizli Hazineler",
    ["Description"]="Babam bu anahtarı sana vermemi söyledi. Evin arkasındaki bir sandığı açtığını söyledi.\n\nAyrıca sana teşekkür etmemi istedi. Ona bir iyilik mi yaptın? Bebeğimi bulduğunu ona söyledin mi?\n\nPekala işte anahtar. Ve teşekkür ederim YOUR_NAME. Teşekkür ederim! Çok iyi bir YOUR_GENDER!",
    ["Objectives"]="Joseph'in Anahtarı'nı Joseph'in Sandığı'na getir.",
    ["Progress"]="Bu sandık eski ve kirle kaplı.",
    ["Completion"]="Anahtar kilide uyuyor ve sandık açılıyor...",
    ["minlevel"]="50",
    ["questlevel"]="60",
    }, -- end Hidden Treasures

    -- Gizelton Caravan
    -- Cork -> Cork (MobNpcData.lua)
    -- Smeed -> Smeed (MobNpcData.lua)
    -- Gizelton Caravan -> Gizelton Kervanı
    -- Mannoroc Coven -> Mannoroc Cadılar Meclisi
    -- Scrabblescrew's Camp -> Scrabblescrew Kampı
    ["5943"] = {
    ["Title"]="Gizelton Kervanı",
    ["Description"]="Becerikli bir YOUR_RACE gibi görünüyorsun. Belki biraz para kazanmak istiyorsundur? Cork ve ben bir çuval para kazanmak için bu kervanı başlattık; bir kova para kazanmanın tehlikelerini az biliyorduk!\n\nİleride Mannoroc Cadılar Meclisi var... normalde iblisler bizi görmezden gelir ama bu sefer bir şey kodoları ürküttü. Mannoroc Cadılar Meclisi'nin yanından kervanı koruman için sana para ödeyeceğim. Güvenle geçtikten sonra ödülünü Scrabblescrew Kampı'ndaki iş ortağımız Smeed'den alabilirsin.",
    ["Objectives"]="Gizelton Kervanı'na Mannoroc Cadılar Meclisi içinden eşlik et. Ödülün için Scrabblescrew Kampı'ndaki Smeed ile konuş.",
    ["Progress"]="Biliyor musun, o kervan bir gün yok olursa mahvolurum! Kervan hakkında kötü haber getiren sen değilsin, değil mi?\n\n<Smeed alnını siler.>\n\nAçgözlülük tanrıçasına şükürler olsun!",
    ["Completion"]="Gizelton Kervanı'nı korumak için bu kadar çok para ödemenin karlı bir teklif olduğundan emin değilim. Cork ve Rigger haftada sadece bir altın sikke kazanıyor ama kodolarımın parasını ödemeye devam ettikleri sürece işlerini nasıl yürüttükleri umurumda değil.",
    ["minlevel"]="32",
    ["questlevel"]="38",
    }, -- end Gizelton Caravan

    -- In Dreams
    -- Taelan Fordring -> Taelan Fordring (MobNpcData.lua)
    -- Tirion -> Tirion (MobNpcData.lua)
    -- Grand Crusader -> Büyük Haçlı (MobNpcData.lua)
    -- Hearthglen -> Hearthglen (ZoneData.lua)
    -- Lordaeron -> Lordaeron (ZoneData.lua)
    ["5944"] = {
    ["Title"]="Rüyalarda",
    ["Description"]="Çok uzun zamandır Büyük Haçlı'nın bir kuklasıydım. Kızıl Haçlı Seferi'nin dönüştüğü şeye karşı savaşmak için ne sebep vardı? On yıllar oldu ama babamın anıları; o değerli anılar, beni hayatta tutan şey oldu.\n\nRüyalar görüyorum, yabancı. Bu rüyalarda babam yanımda. Tarikat'a kabul edilirken gururla yanımda duruyor. Afet lejyonuyla omuz omuza savaşıyoruz. İttifak'a, Lordaeron'a onur getiriyoruz.\n\nArtık rüya görmek istemiyorum.\n\nBeni ona götür.",
    ["Objectives"]="Taelan Fordring'e Hearthglen dışına kadar eşlik et.",
    ["Progress"]="<Tirion soğukkanlılığını yeniden kazanır.>",
    ["Completion"]="Oğlumun bu canavarların elindeki ölümü olaysız geçmeyecek. Tarikat'ın yeniden doğduğunu bilerek teselli bul.\n\nŞimdi yeni Gümüş El Tarikatı'nın Yüce Lordu olarak yerimi alıyorum.\n\nGeçmişimin bu mülkleri - yaptığın her şey için sunabileceğim tek şey bunlar. Lütfen bunları minnettarlığımın bir sembolü olarak kabul et; hepsi yıllar boyunca bana iyi hizmet etti.\n\nDaha iyi zamanlarda tekrar karşılaşmak ve geçmiş günleri... zorlu savaşları... kurtarılan rüyaları yad etmek dileğiyle...",
    ["minlevel"]="52",
    ["questlevel"]="60",
    }, -- end In Dreams

    -- Rampaging Giants
    -- Tyrande Whisperwind -> Tyrande Fısıltırüzgarı (MobNpcData.lua)
    -- Rivern Frostwind -> Rivern Dondururüzgar (MobNpcData.lua)
    -- Shy-Rotam -> Shy-Rotam (MobNpcData.lua)
    ["5981"] = {
    ["Title"]="Çılgına Dönen Devler",
    ["Description"]="Yaklaşık 4.000 yıl önce Tyrande Fısıltırüzgarı, çılgına dönen devlerin elinden buzkılıç kraliçesinin hayatını kurtardı. O zamandan beri buzkılıçlar Gece elflerinin müttefiki olmuştur.\n\nBir zamanlar buzkılıçlar için tehlike oluşturan bu aynı devler hâlâ buradan pek uzakta olmayan bir yerde varlıklarını sürdürüyorlar. Buzbalyozu olarak adlandırılıyorlar ve güneydeki büyük vadiyi ele geçirdiler.\n\nBuzkılıçlara sadakatini kanıtla; buzkılıç kraliçesi Shy-Rotam adına bu devleri öldür!",
    ["Objectives"]="Rivern Dondururüzgar 4 Buzbalyozu Devı ve 4 Buzbalyozu Koruyucusu öldürmeni istiyor.",
    ["Progress"]="Kendini kanıtlamaya devam etmelisin, YOUR_NAME.",
    ["Completion"]="Mükemmel, YOUR_NAME. Kararlılığın usulüne uygun olarak not edildi.",
    ["minlevel"]="58",
    ["questlevel"]="60",
    }, -- end Rampaging Giants

    -- Unfinished Business
    -- Kirsta Deepshadow -> Kirsta Deringölge (MobNpcData.lua)
    -- Hearthglen -> Hearthglen (ZoneData.lua)
    -- Western Plaguelands -> Batı Veba Toprakları (ZoneData.lua)
    -- Stormwind -> Fırtınaşehri (ZoneData.lua)
    ["6004"] = {
    ["Title"]="Bitmemiş İş",
    ["Description"]="Biraz hasar vermek ve Hearthglen'in savunmasının gücünü ölçmek için gözcü olarak gönderildim. İttifak'taki bazı insanlar bu küçük kasabanın tarihi önemden daha fazlasına sahip olduğunu düşünüyor. Bu önemin ne olduğunu sorgulamak benim işim değil, ama ne olursa olsun dinlenene kadar devam edecek durumda değilim.\n\nRazıysan yardım için cömertçe ödeme yaparım. Buranın güneyinden, kurdukları küçük siper yakınındaki ordugahlarından başla. Yeterince güçlü olduğunu kanıtlarsan ana hedefim konusunda yardımını alabilirim.",
    ["Objectives"]="Batı Veba Toprakları'ndaki Kirsta Deringölge'ye dönmeden önce 2 Kızıl Tabip, 2 Kızıl Avcı, 2 Kızıl Büyücü ve 2 Kızıl Şövalye öldür.",
    ["Progress"]="Nasıl gidiyor, YOUR_NAME? Düşündüğünden daha mı güçlüler? Umarım değildir. Burada devam edeceksem bu senden zaten istediğimden çok daha fazla güç gerektirecek.",
    ["Completion"]="Aferin, YOUR_NAME. Onlarla bu kadar hızlı ilgilenmene şaşırdım. Teşekkür ederim.\n\nKızıl Haçlı Seferi'ni ve yöntemlerini onaylayan biriyle henüz karşılaşmadım. Fırtınaşehri'ndeki diğer herkes kadar Işık'a inanıyorum ama hareketlerine sadık olmayan herkesi... masumları bile öldürmek istediklerini gösterdiler.",
    ["minlevel"]="50",
    ["questlevel"]="56",
    }, -- end Unfinished Business

    -- Zaeldarr the Outcast
    -- Zaeldarr the Outcast -> Sürgün Zaeldarr (MobNpcData.lua)
    -- Zaeldarr -> Zaeldarr (MobNpcData.lua)
    -- Caretaker Alen -> Bakıcı Alen (MobNpcData.lua)
    -- Light's Hope Chapel -> Işık Umudu Şapeli (ZoneData.lua)
    -- Undercroft -> Mahzen
    ["6021"] = {
    ["Title"]="Sürgün Zaeldarr",
    ["Description"]="Veba topraklarında yaşadığımız tüm dertlerden sonra... hırsızlar hakkında da endişelenmemiz gerektiğine inanabiliyor musun? Ve sadece normal hırsızlar değil, troll hırsızları.\n\nVe sadece normal troll hırsızları da değil. Ölü troll hırsızları!\n\nSürgün Zaeldarr adındaki bu büyük, ölü troll tarafından yönetiliyorlar ve gece buraya gelip aşağıdaki çukurdan ceset çalıyorlar, sonra onları batıdaki kötü, ölü troll sığınaklarına--Mahzen'e--götürüyorlar.\n\nOraya git ve Zaeldarr'ı ortadan kaldır, YOUR_NAME. Onun yaramazlıklarından ölümüne bıktım!",
    ["Objectives"]="Zaeldarr'ın Kafası'nı Işık Umudu Şapeli'ndeki Bakıcı Alen'e getir.",
    ["Progress"]="Sığınağı buldun mu, YOUR_NAME? Zaeldarr'ın icabına baktın mı?",
    ["Completion"]="Harika, onu yakaladın! Ve umarım çetesine de bir ders vermişsindir!",
    ["minlevel"]="50",
    ["questlevel"]="55",
    }, -- end Zaeldarr the Outcast

    -- To Kill With Purpose
    -- Nathanos -> Nathanos (MobNpcData.lua)
    -- Dark Lady -> Karanlık Hanım (MobNpcData.lua)
    -- Corin's Crossing -> Corin Kavşağı (ZoneData.lua)
    ["6022"] = {
    ["Title"]="Bir Amaçla Öldürmek",
    ["Description"]="Mülkümde kaldığın sürece bir amaç doğrultusunda öldürürsün.\n\nİlk görevin tazılarımı beslemektir.\n\nBu havanı ve havan elini alıp Corin Kavşağı'na seyahat et. Oraya vardığında katledilecek zengin bir Afet seçkisi bulacaksın. Taze taze leşlerinden canlı çürük ihtiyacım var. O canlı çürüğü alıp havanda öğüt, sonra pıhtılaşması için beklet. Pıhtılaşmış çürüğü buraya geri getir.\n\nVe aptal, hortlaklardan gelen canlı çürüğün çok uzun süre 'canlı' kalmadığını fark et. Hızlıca öldürmelisin!",
    ["Objectives"]="Doğudaki Corin Kavşağı'na seyahat et ve kasabada ikamet eden Afet'i katlet. 10 dakikadan kısa bir sürede 7 parça Canlı Çürük topla. Canlı Çürük'ü Pıhtılaşmış Çürük haline getirmek için Havan ve Havan Eli'ni kullan.",
    ["Progress"]="Ağlıyor musun? Bu senin için fazla 'sıkıcı'ysa, 'kahraman,' Karanlık Hanım'a geri dönmeni ve çiftliğimde gördüğün korkunç kötü muameleyi ona bildirmeni öneririm.\n\nŞimdi gözümün önünden kaybol!",
    ["Completion"]="Hayal kırıklığı. Seni tazılarıma yem ediyor olacağımı umuyordum, onun yerine.\n\n<Nathanos iç çeker.>\n\nŞey, en azından yiyecek bir şeyleri olacak.",
    ["minlevel"]="54",
    ["questlevel"]="58",
    }, -- end To Kill With Purpose

