    -- Light's Hope Chapel -> Işık Umudu Şapeli (ZoneData.lua)
    -- Eastern Plaguelands -> Doğu Veba Toprakları (ZoneData.lua)
    ["6030"] = {
    ["Title"]="Dük Nicholas Zverenhoff",
    ["Description"]="Umbranse adıyla buralarda bulunan münzevi bir medyum, Gümüş Şafak'a adeta edebi bir başyapıt sağladı... muhtemelen şimdiye kadar yazıldığını gördüğüm en büyük saçmalık koleksiyonuna denk gelen bir şey.\n\nŞafak'ın en saygı duyulan liderlerinden biri olan Dük Nicholas Zverenhoff harika bir dilbilimcidir. Bunu benim için ona götürür müsün - bir ödül karşılığında elbette? Işık Umudu Şapeli - şu anda Doğu Veba Toprakları'nın uzak doğu kısmındaki orada bulunuyor.",
    ["Objectives"]="'Ruh Konuşma Çalışmaları' kitabını Doğu Veba Toprakları'ndaki Işık Umudu Şapeli'nde bulunan Dük Nicholas Zverenhoff'a teslim et.",
    ["Progress"]="Bu sıkıntılı zamanlarda Işık sana rehberlik etsin, YOUR_CLASS. Karanlığın ve umutsuzluğun ortasındaki bu umut fenerine seni ne getirdi?",
    ["Completion"]="Bu... bana getirdiğin çok özel bir kitap. Bu durumda 'özel' kelimesinin 'benzersiz ve muhtemelen aydınlatıcı' anlamına geldiğini söylemek isterdim ama bu henüz belli değil.\n\n'Ooooooo?' Aklı başında kim böyle bir şey düşünür?\n\nPekala, Gregor'un bahsettiği bu Umbranse'i duymuştum, bu yüzden bu değersiz değil. Onu deşifre etmek için elimden geleni yapacağım. Sana gelince... lütfen bunu al - Gümüş Şafak'ın ikramı. Buradayken belki bize yardım edebileceğin başka şeyler de vardır.",
    ["minlevel"]="50",
    ["questlevel"]="52",
    }, -- end Duke Nicholas Zverenhoff

    -- Runecloth
    -- Meilosh -> Meilosh (MobNpcData.lua)
    -- Timbermaw -> Tahtaağız
    -- Timbermaw Hold -> Tahtaağız Kalesi (ZoneData.lua)
    ["6031"] = {
    ["Title"]="Rün Kumaşı",
    ["Description"]="Tahtaağız'da memnunuz. Yabancıları sevmeyiz. Bu bizim için iyi ama ticaret için kötü.\n\nÇok zaman geçmeden nadir bir Gece elfi arkadaş Tahtaağız'a geldi ve rün kumaşından bir pelerin giyiyordu. Rün kumaşı aramızda nadirdir ama pelerin o kadar güzeldi ki halkım daha fazla rün kumaşından giysi yapmamı istiyor.\n\nBana rün kumaşı getirir misin? Yeterince getirirsen sana ticarette bir şey vereceğim.",
    ["Objectives"]="Tahtaağız Kalesi'ndeki Meilosh'a 30 Rün Kumaşı getir.",
    ["Progress"]="Rün kumaşı yanında mı? Halkım daha fazla rün kumaşı eşyası için sabırsızlanıyor!",
    ["Completion"]="Ah, kumaşı getirdin. Çok güzel bir malzeme!\n\nTeşekkür ederim, YOUR_NAME. Sen gerçek bir arkadaşsın. Lütfen takas olarak bunu kabul et.",
    ["minlevel"]="50",
    ["questlevel"]="55",
    }, -- end Runecloth

    -- Sacred Cloth
    -- Meilosh -> Meilosh (MobNpcData.lua)
    -- Timbermaw -> Tahtaağız
    -- Timbermaw Hold -> Tahtaağız Kalesi (ZoneData.lua)
    ["6032"] = {
    ["Title"]="Kutsal Kumaş",
    ["Description"]="Tahtaağız halkı rün kumaşı hissinden keyif alsa da bizim için kutsal değildir. Ama ay kumaşı kutsaldır.\n\nBana bu kutsal kumaştan küçük bir miktar getir, ben de sana gizli bir biçimlendirme tekniği öğreteyim.",
    ["Objectives"]="Tahtaağız Kalesi'ndeki Meilosh'a 2 Ay Kumaşı getir.",
    ["Progress"]="Ay kumaşını getirdin mi, YOUR_NAME?",
    ["Completion"]="Ah, çok güzel. Bu ay kumaşı halkımız için kutsal olan giysiler için kullanılacak. Teşekkür ederim, YOUR_NAME. Şimdi seni eğiteceğim.",
    ["minlevel"]="50",
    ["questlevel"]="55",
    }, -- end Sacred Cloth

    -- When Smokey Sings, I Get Violent
    -- Smokey -> Dumanlı (MobNpcData.lua)
    -- Plaguewood -> Vebaormanı (ZoneData.lua)
    -- Light's Hope -> Işık Umudu (ZoneData.lua)
    ["6041"] = {
    ["Title"]="Dumanlı Şarkı Söylediğinde Şiddetlenirim",
    ["Description"]="Sen malzemeleri toplarken insanlarımdan bazılarına yıkmamız gereken Afet binalarını işaretlettim.\n\nPlan şöyle: Sana özel bileşimimden ten çubuk vereceğim. Onları Vebaormanı'na götürecek ve patlatma için işaretlettiğim Afet yapılarının içine yerleştireceksin.\n\n<Dumanlı parmaklarını şıklatır.>\n\nBing! İşte bu kadar kolay.",
    ["Objectives"]="Işık Umudu'nun kuzeybatısındaki Vebaormanı'na seyahat et. Her binanın içine yerleştirilmiş Patlatma İşareti'nde Dumanlı'nın Özel Bileşimi'ni kullanarak 8 Afet Yapısını Yok Et. Dumanlı Zigguratları ve Kesimhaneleri işaretletti.\n\nBombayı yerleştirdikten sonra binadan çık ve el emeğine hayran kal.\n\nBu arada Dumanlı'nın Özel Bileşimi biraz... kararsızdır.",
    ["Progress"]="Özel bileşimden birkaç çubuk daha yapacak malzemem kaldı. Daha fazlasına ihtiyacın olursa yaşlı Dumanlı'ya bildirmene bakar.",
    ["Completion"]="Hatırladığımdan çok daha esmersin. Şöyle bir havan var; 'Yüksek patlayıcılı bir bombayla kavrulmuşum' diyen bir hava.\n\n<Dumanlı güler.>\n\nHer neyse! İşte ganimetten payın. Yanıkları yatıştırmaya yardımcı olması için fazladan bir şeyler daha ekledim.",
    ["minlevel"]="54",
    ["questlevel"]="58",
    }, -- end When Smokey Sings, I Get Violent

    -- Un-Life's Little Annoyances
    -- Nathanos -> Nathanos (MobNpcData.lua)
    ["6042"] = {
    ["Title"]="Yaşamsızlığın Küçük Rahatsızlıkları",
    ["Description"]="O iğrenç yarasalardan birine çarpmadan bu çiftlikten iki adım uzaklaşamazsın. Tazıları çıkarıp o lanet, kirli yarasalar tarafından taciz edilmeden Afet'i katledebilmek istiyorum. Belli ki zamanımla gün be gün düşüncesizce yarasaları öldürmekten daha iyi yapacak işlerim var. Senin ise yok.\n\nNe? Eğitimin mi? Eğitimin bu! Şimdi gözümün önünden kaybol ve o kanatlı iblislerden makul sayıda öldürene kadar geri gelme. Beni hayal kırıklığına uğratma.",
    ["Objectives"]="20 Zehirli Veba Yarasası ve 10 Canavarca Veba Yarasası katlet. Bitiğinde Nathanos Vebalanetleyen'e dön.",
    ["Progress"]="Daha kötü olabilirdi. Sana yarasa gübresi toplatıyor olabilirdim.\n\n<Nathanos derin düşünceler içinde sana dik dik bakar.>\n\nHrm... Hey! Bir dakika. Nereye gidiyorsun?",
    ["Completion"]="Biraz öfke ve gazabın neler başarabileceği inanılmaz.",
    ["minlevel"]="54",
    ["questlevel"]="58",
    }, -- end Un-Life's Little Annoyances

    -- Get Me Out of Here!
    -- Hornizz -> Hornizz (MobNpcData.lua)
    -- Melizza -> Melizza (MobNpcData.lua)
    -- Hornizz Brimbuzzle -> Hornizz Brimbuzzle (MobNpcData.lua)
    -- Melizza Brimbuzzle -> Melizza Brimbuzzle (MobNpcData.lua)
