    -- Maraudines -> Maraudinler
    -- Kodo Graveyard -> Kodo Mezarlığı
    -- Desolace -> Desolace (ZoneData.lua)
    ["6132"] = {
    ["Title"]="Beni Buradan Çıkar!",
    ["Description"]="Beni buradan çıkar!\n\nMaraudinler ile konuşmak için Mızraklar Vadisi'ne geldim. Onlarla biraz iş yapabileceğimi düşündüm... ama konuşmak istemiyorlar! Sanırım beni yemek istiyorlar!\n\nBeni buradan çıkar, doğudaki kodo mezarlığının yanındaki kampımızda bulunan kardeşim Hornizz sana büyük ödeme yapacak!\n\nHadi acele edelim, YOUR_NAME. Daha iki dakika önce bazı kentaurların pişirme kazanları için odun almaktan bahsettiklerini duydum...",
    ["Objectives"]="Melizza Brimbuzzle'a eşlik et, ardından Desolace'taki Kodo Mezarlığı'nda buluna Hornizz Brimbuzzle ile konuş.",
    ["Progress"]="Kız kardeşim Melizza'yı gördün mü? Her zaman hareket halindedir, bu da onu her zaman başını belaya sokar.",
    ["Completion"]="Kız kardeşim Melizza geleceğini söylemişti. İçinde bulunduğu beladan onu çıkardığın için çok teşekkürler; muhtemelen şimdiden yeni bir tane bulmuş olması çok kötü!",
    ["minlevel"]="34",
    ["questlevel"]="39",
    }, -- end Get Me Out of Here!

    -- The Ranger Lord's Behest
    -- Quel'Lithien -> Quel'Lithien (ZoneData.lua)
    -- Quel'Thalas -> Quel'Thalas
    -- Eastern Plaguelands -> Doğu Veba Toprakları (ZoneData.lua)
    ["6133"] = {
    ["Title"]="Korucu Lordunun İsteği",
    ["Description"]="Quel'Lithien kulübesinin Yüksek elfleri bana ait olan bir şeye sahip, YOUR_CLASS: Ölümlü olarak hayatımı detaylandıran bir belge.\n\nSormadan önce; hayır, kesinlikle böyle bir bilgiye erişim hakkın yok. Sadece sana söylediğimi yap, solucan: Sicili geri al.\n\nVe aptal, arkanda olabildiğince çok çatışma ve keder bıraktığından emin ol. Onları acı çekerken bırak...",
    ["Objectives"]="Doğu Veba Toprakları'nın kuzey sınırlarına seyahat et ve Quel'Thalas Sicili'ni geri al. Eşya Quel'Lithien kulübesinde bir yerdedir.\n\nAyrıca 8 Korucu, 8 Yolgezer ve 8 Ormancı katletmelisin.",
    ["Progress"]="Beni bekletme, YOUR_CLASS.",
    ["Completion"]="Sicili okumadığına inanıyorum. Sen bile bu kadar aptalca bir şey yapmazdın...",
    ["minlevel"]="54",
    ["questlevel"]="60",
    }, -- end The Ranger Lord's Behest

    -- Ghost-o-plasm Round Up
    -- Hornizz Brimbuzzle -> Hornizz Brimbuzzle (MobNpcData.lua)
    -- Valley of Bones -> Kemikler Vadisi
    -- Magram -> Magram
    -- Dead Goliaths -> Ölü Devler
    -- Desolace -> Desolace (ZoneData.lua)
    ["6134"] = {
    ["Title"]="Hayalet-o-plazma Toplama",
    ["Description"]="Güneydoğuda, Magram hayaletlerinin musallat olduğu bir vadi var, Kemikler Vadisi. Korkunç kulağa geliyor, değil mi? Şey, Magram için ne kadar korkunç olduğunu bir düşün! O yerden hayalet enerjisi yakalasaydık, o kentaurlar için çok şey edeceğine bahse girerim.\n\nAl, bu hayalet mıknatısları kutusunu al. Vadideki iki büyük iskeletin, Ölü Devler'in arasına bir tane yerleştirirsen hayaletler ona doğru sürüklenecektir. Mesafeni koru, hayaletleri ortadan kaldır ve hayalet-o-plazmalarını al--Magram'a satacağımız şey bu.",
    ["Objectives"]="Desolace'taki Hornizz Brimbuzzle'a 8 Hayalet-o-plazma ve Hayalet Mıknatısları Kutusu getir.",
    ["Progress"]="Hayalet-o-plazmam nerede, YOUR_NAME?",
    ["Completion"]="İşte orada! Sanırım birazı üzerine de bulaşmış. Biraz vıcık vıcık, ha?\n\nŞey, tüm bu zahmet için çok teşekkürler, YOUR_NAME. Bu şey bir servet değerinde olacak... Kentaurları ne olduğuna ikna edebilirsem!",
    ["minlevel"]="34",
    ["questlevel"]="39",
    }, -- end Ghost-o-plasm Round Up

    -- Duskwing, Oh How I Hate Thee...
    -- Duskwing -> Alacakaranlıkkanat (MobNpcData.lua)
    -- Nathanos Blightcaller -> Nathanos Vebalanetleyen (MobNpcData.lua)
    -- Marris Stead -> Marris Çiftliği (ZoneData.lua)
    ["6135"] = {
    ["Title"]="Alacakaranlıkkanat, Oh Senden Nasıl da Nefret Ediyorum...",
    ["Description"]="Şimdiye kadar sana atadığım görevleri tamamladın; en zamanında olmasa bile.\n\nSanırım bir meydan okumaya hazır olduğunu düşünüyorsun. Evet... Evet, aptal, belki de daha karmaşık görevler dizisine hazırsındır.\n\nAlbinos iblis yarasa Alacakaranlıkkanat tam buranın kuzeyindeki kırsalda dolaşıyor. Onu takip et ve yok et. Onun beyaz kürkünden bir parçayla bana dön, ben de seni ödüllendireyim.",
    ["Objectives"]="Alacakaranlıkkanat'ı bul ve katlet. Cesedinden Alacakaranlıkkanat'ın Kürk Parçası'nı çıkar ve Nathanos Vebalanetleyen'e dön.\n\nAlacakaranlıkkanat'ın Marris Çiftliği'nin kuzeyindeki kırsal alanda dolaştığı söylenir.",
    ["Progress"]="Bu meydan okumayı tek başına üstlenmeni tavsiye etmem, YOUR_CLASS.",
    ["Completion"]="Mükemmel iş, aptal. Bu kürkü kullanabileceğin bir şeye dönüştüreceğim.",
    ["minlevel"]="56",
    ["questlevel"]="60",
    }, -- end Duskwing, Oh How I Hate Thee...

    -- The Corpulent One
    -- Borelgore -> Borelgore (MobNpcData.lua)
    -- Nathanos Blightcaller -> Nathanos Vebalanetleyen (MobNpcData.lua)
    -- Light's Hope -> Işık Umudu (ZoneData.lua)
    -- Northdale -> Kuzeyvadi (ZoneData.lua)
    -- Eastern Plaguelands -> Doğu Veba Toprakları (ZoneData.lua)
    ["6136"] = {
    ["Title"]="Tombul Olan",
    ["Description"]="Gümüş Şafak ordugahı Işık Umudu'nun ötesinde ve Kuzeyvadi'nin batısında, tombul kurtçuk canavarı Borelgore'u bulacaksın.\n\nO canavara tam alaylar dolusu asker kaybettim. Boyutunun sınırı yok! Ne kadar çok yerse gövdesi o kadar büyüyor...\n\nCanavar seni yutsa hiçbir duygusal zarar görmeyecek olsam da galip gelenin sen olmanı tercih ederim. Bu görev için başkalarının yardımına başvurmanı öneririm. Borelgore'un kendisine saldırma aptallığında bulunan küçük taburları yuttuğu bilinmektedir.",
    ["Objectives"]="Doğu Veba Toprakları'nın kuzey çoraklıklarında Borelgore'u bul ve onu yok et. Görev tamamlandığında Nathanos Vebalanetleyen'e dön.",
    ["Progress"]="Senden nefret ettiğimi yakın zamanda söyledim mi?",
    ["Completion"]="Böyle devam et, seni aptaldan birinci sınıf zihinsel engelliye terfi ettirmem gerekebilir.",
    ["minlevel"]="56",
    ["questlevel"]="60",
    }, -- end The Corpulent One

    -- Brother Anton
    -- Brother Anton -> Anton Kardeş (MobNpcData.lua)
    -- Anton -> Anton (MobNpcData.lua)
    -- Kalimdor -> Kalimdor (ZoneData.lua)
    -- Desolace -> Desolace (ZoneData.lua)
    -- Nijel's Point -> Nijel Karakolu (ZoneData.lua)
    ["6141"] = {
    ["Title"]="Anton Kardeş",
    ["Description"]="Silah arkadaşım Anton Kardeş, uzak Kalimdor'da, Desolace olarak bilinen bir diyarda ölümsüz istilası söylentileri duydu. Anton hemen ölümsüz tehdidini aramak ve yok etmek için o yere bilet aldı!\n\nKendisine yardım edecek cesaret ve kararlılığa sahip kişileri arıyor. Kalbin doğruysa Anton ile konuş. Desolace'ta, İttifak kasabası Nijel Karakolu'ndadır.",
    ["Objectives"]="Desolace'taki Anton Kardeş ile konuş.",
    ["Progress"]="",
    ["Completion"]="Doğudan yardım geldiği haberini aldım. Bu söylentilerin kaynağı sen misin? Kızıl Kardeş'e haçlı seferinde yardım etmek için mi buraya geldin?\n\nÖyleyse yakından dinle...",
    ["minlevel"]="34",
    ["questlevel"]="39",
    }, -- end Brother Anton

    -- Clam Bait
    -- Mai'Lahii -> Mai'Lahii (MobNpcData.lua)
    -- Shadowprey Village -> Gölgeavı Köyü (ZoneData.lua)
    ["6142"] = {
    ["Title"]="Deniz Kabuklusu Yemi",
    ["Description"]="Balıkçı havası var sende, YOUR_CLASS! Balık tutmayı çok severim - tüm hayatım boyunca balık tuttum. Kullanılacak en iyi yem yumuşak kabuklu deniz kabuklusu etidir; balıklar karşı koyamaz, ne demek istediğimi anlıyor musun?\n\nKuzeyde kıyının açıklarında batık bir gemi bulacaksın. Yumuşak kabuklu deniz kabukluları bölgenin her yerine saçılmıştır. Bana 10 parça yumuşak kabuklu deniz kabuklusu eti getirirsen sana karşılığında bir şey vereceğim.",
    ["Objectives"]="10 parça Yumuşak Kabuklu Deniz Kabuklusu Eti bul ve Gölgeavı Köyü'ndeki Mai'Lahii'ye geri getir.",
    ["Progress"]="Taze yumuşak kabuklu deniz kabuklusu etiyle balık tutmaya gitmek için sabırsızlanıyorum; ihtiyacım olan 10 parçayı getirdin mi?",
    ["Completion"]="Mükemmel dostum, bu tam da büyü doktorunun baş ağrım için yapmamı söylediği şey. 'Mai'Lahii - balık tutmaya git. Seni daha iyi hissettirecek' diyor\n\nŞey, şimdiden daha iyi hissediyorum, teşekkürler dostum!",
    ["minlevel"]="31",
    ["questlevel"]="35",
    }, -- end Clam Bait

    -- Other Fish to Fry
    -- Drulzegar -> Drulzegar (MobNpcData.lua)
    -- Ranazjar Isle -> Ranazjar Adası (ZoneData.lua)
    -- Shadowprey -> Gölgeavı (ZoneData.lua)
    -- Desolace -> Desolace (ZoneData.lua)
    ["6143"] = {
    ["Title"]="Kızartılacak Başka Balıklar",
    ["Description"]="Belki duymuşsundur belki duymamışsındır... mürettebatım ve ben kuzeydeki batık geminin kuzeyindeki Ranazjar Adası yakınlarında balık tutuyorduk. Eskiden her zaman orada balık tutardık; şimdi tek yaptığım düşen yoldaşlarımın intikamını almanın bir yolunu düşünmek.\n\nNaga bir sabah bize saldırdı, ben hariç herkesi öldürdü.\n\nVicdanım bu suçlulukla baş edemiyor, YOUR_CLASS; gidip o nagaları benim için kızartmanı istiyorum. Çabanın karşılığını vereceğim; bu konuda bana yardım edebileceğini düşünüyor musun?",
    ["Objectives"]="7 Slitherblade Mermidonu, 7 Slitherblade Nagası ve 5 Slitherblade Büyücüsü katlet, ardından Desolace'taki Gölgeavı'nda Drulzegar ile konuş.",
    ["Progress"]="Naga üzerimize kaos saçtığında yardım için haykıran seslerini hâlâ duyuyorum. Bu kötü dizim olmasaydı gidip o lanet nagaları öldürmene yardım ederdim!\n\nGenellikle onları yüzeyin altındaki mercan kayalıklarının derinliklerinde bulabilirsin... pusuda bekliyorlar... plan yapıyorlar...",
    ["Completion"]="Naganın bozguna uğratıldığı haberini duymak ne kadar tatlı olsa da kalbim hâlâ boş hissediyor. Hayatımın geri kalanında hepsini öldürtmeye adanacağım.\n\nİşte dostum, söz verdiğim gibi ödülün. Mürettebatıma karşı işledikleri nefret dolu eylem yüzünden nagaların kızardığını bilmenin hazzının yanında küçük kalır.",
    ["minlevel"]="32",
    ["questlevel"]="36",
    }, -- end Other Fish to Fry

