["9292"] = {
    ["Title"]="Çatlak Nekrotik Kristal",
    ["Description"]="Düşen iğrençliğin cesedi üzerinde, nekrotik enerjiyle yavaşça çarpan çatlak bir kristal keşfediyorsun.",
