["7875"] = {
    ["Title"] = "Gümüşkanat Gaspçılarını Bastır",
    ["Description"] = "Aşenağaç ormanının vahşi doğası Hordenin gücüne boyun eğecek, YOUR_RACE. Gümüşkanat'ın söylediği veya yaptığı hiçbir şey egemen gerekliliğimizi durduramaz. Kalimdor Horde'ye aittir. Haklı olarak bize ait olanı hasat etmemizi engellemeye nasıl cüret ederler!NEW_LINENEW_LINEİlerlememizi yavaşlatmaya yönelik zayıf girişimlerini keserken gururun göğsünde kabarmasına izin ver. Gümüşkanat Gözcüleri'ni yok et ve bir Onur Nişanı kazan. Böyle bir Nişan ile bana geri dön, YOUR_NAME, ve ödüllendirileceksin.",
    ["Objectives"] = "Savaşşarkısı Kanyonu'na gir ve İttifak'ı mağlup et, bir Savaşşarkısı Kanyonu Onur Nişanı kazan ve bunu Mor'shan Üs Kampı'ndaki Kaptan Shatterskull'a getir.",
    ["Progress"] = "Düşmanlarımızın kanı bir onur nişanıdır. Böyle bir nişanın var mı?",
    ["Completion"] = "<Kaptan Shatterskull zaferle kükrer>NEW_LINENEW_LINEDaha ne kadar dayanabilirler? Geri çekilmeleri için Horde'nin ellerinde daha kaç İttifak pisliği yok olmalı? Bunu sadece zaman gösterecek, YOUR_RACE...",
    ["minlevel"] = "40",
    ["questlevel"] = "49"
},

["5213"] = {
    ["Title"] = "Aktif Ajan",
    ["Description"] = "Stratholme'un daha da derinlerine inmen gerekecek, YOUR_NAME.NEW_LINENEW_LINEİlk kapıların ötesinde zigguratları bulacaksın. Afet'in bu yapılardan büyük güç çektiğini biliyoruz. Zigguratları ara ve keşfedebileceğin her türlü bilgiyle geri dön.",
    ["Objectives"] = "Stratholme'a seyahat et ve zigguratları ara. Betina Bigglezink'e yeni Afet Verileri bul ve getir.",
    ["Progress"] = "Bu yeni aktif veba ajanının ne olabileceğini keşfetmek üzereyiz!",
    ["Completion"] = "Şaşırtıcı! Bunu parçalara ayırıp analiz etmek aylar alacak. Gümüş Şafak çabaların için sana teşekkür eder, YOUR_NAME.NEW_LINENEW_LINELütfumuzla, bu Şafak Mührü veya bu Şafak Rünü arasından seçimini yap. Bizim adımıza veba taşları toplamak için standart bir Gümüş Şafak Yetki Belgesi yerine bunlardan birini kullanabilirsin. Seninkini kaybedersen, benimle konuş, sana yenisini temin edeyim.",
    ["minlevel"] = "55",
    ["questlevel"] = "60"
},

["6163"] = {
    ["Title"] = "Ramstein",
    ["Description"] = "Bunalmış durumdaydım. Tam bu noktada durdum... Lordaeron'u savunmak için yerimi korudum. Çiftlik ve üzerindeki her şey devasa bir Afet dalgası tarafından basıldı.NEW_LINENEW_LINESefil şey. Pislik. Açık göğüs kafesinden sakatatlar sarkarak üzerimde süzüldü.NEW_LINENEW_LINEAfet olarak uyandım. Çok uzun süre çaresiz kaldım. Zihnim Lik Kralı'nınkiyle birleşmişti.NEW_LINENEW_LINEBenim için geldi... bir şekilde, bir yerde geleceğini biliyordum. Özgürüm.NEW_LINENEW_LINEVe şimdi, intikamımı almalıyım - hayatımı benden alan şeyden intikamımı. Onu yok et.",
    ["Objectives"] = "Stratholme'a seyahat et ve Tıkan Nathanos için bir hatıra olarak kafasını al.",
    ["Progress"] = "Sylvanas beni kurtardıktan sonra, aylarca bu çorak topraklarda canavarı avladım. Stratholme'un güvenliğine kaçtı. Piç...",
    ["Completion"] = "Merak ediyorum... merhamet dilemiş midir? Merhametin ne olduğunu bilebilir miydi?NEW_LINENEW_LINE<Nathanos tükürür.>NEW_LINENEW_LINEBu canavarın kafasını duvarıma asacağım.NEW_LINENEW_LINESampiyonlarımdan birinin arasında bir yer kazandın, YOUR_NAME.NEW_LINENEW_LINE<Nathanos selam durur.>",
    ["minlevel"] = "56",
    ["questlevel"] = "60"
},

["6241"] = {
    ["Title"] = "Kışdüşüşü Faaliyeti",
    ["Description"] = "Tahtasaqallılar kendi başlarına takılma eğilimindedir, YOUR_NAME. Güvenilirliğini kanıtlamış olanlara güvenli geçiş izni versek de, mümkünse diğer furbolg kabilelerinden kaçınmaya çalışırız.NEW_LINENEW_LINESon zamanlarda Kışdüşüşü kabilesinin bize karşı giderek daha düşmanca bir tavır sergilediğini fark ettim. Anlamadıkları her şeye karşı kendi korku ve nefretleriyle tamamen sürüklenmiş, bir öfke durumunda gibiler.NEW_LINENEW_LINESayılarını azaltabilirsen bu bize büyük ölçüde yardımcı olur, YOUR_NAME.",
    ["Objectives"] = "Salfa 6 Kışdüşüşü Totemcisi, 6 Kışdüşüşü İni Nöbetçisi ve 6 Kışdüşüşü İzcisi öldürmeni istiyor.",
    ["Progress"] = "Tahtasaqallılar için yaptıklarını çok takdir ediyoruz, YOUR_NAME. Devam eden çabaların kesinlikle kabilemin güvenini ve saygısını kazanacaktır.",
    ["Completion"] = "Yaptıkların için teşekkür ederim. Lütfen bize yardım etmeye devam et, YOUR_NAME. Çağırabileceğimiz çok az müttefikimiz var.",
    ["minlevel"] = "52",
    ["questlevel"] = "56"
},

["7181"] = {
    ["Title"] = "Korrak Efsanesi",
    ["Description"] = "İşgalci Fırtınasivrisi bu bölgedeki tek tehdit değil, asker. Vadideki savaş iki cephede yürütülüyor. Yamyam Kışbaltası trolleri de güç için yarışıyor.NEW_LINENEW_LINEAcımasız ve kurnaz bir canavar olan Kanfırtınası Korrak tarafından yönetiliyorlar.NEW_LINENEW_LINEKorrak'a indirilecek bir darbe, Kışbaltası klanına yıkıcı bir darbe vurabilir. Canavarı katlet ve ödüllendir!",
    ["Objectives"] = "Efsaneye göre, güçlü Kışbaltası trollerinin lideri, Alterac Vadisi sakinlerine zarar vermek için istediği zaman ortaya çıkar.NEW_LINENEW_LINEKorrak kendini gösterecek olursa, onu yok et ve Savaşustası Laggrond'a geri dön.",
    ["Progress"] = "Uyarmadı deme asker, Fırtınasivrisi de Korrak'ı avlıyor.",
    ["Completion"] = "Geriye sadece işgalci Fırtınasivrisi orduları kaldı, asker. Aferin!",
    ["minlevel"] = "51",
    ["questlevel"] = "60"
},

["7202"] = {
    ["Title"] = "Kanfırtınası Korrak",
    ["Description"] = "Bölgenin yerlisi olan Kışbaltası trolleri, kemiklerimizi iğrenç çorbalarına eklemekten başka bir şey istemeyen acımasız vahşilerdir.NEW_LINENEW_LINEOnlara gücümüzü göstermeliyiz!NEW_LINENEW_LINE Liderlik hiyerarşilerini ayrıntılarıyla anlatan tomarları mağaralarından ele geçirdik. Kalıntılar, liderleri Kanfırtınası Korrak'ın, varlığını hissettirmek için bir neden verilene kadar gizli kalma eğiliminde olduğunu gösteriyor.NEW_LINENEW_LINEKorrak'ın ölümü Kışbaltası Klanı'nın ölümü anlamına gelir! Onu katlet ve geri dön.",
    ["Objectives"] = "Efsaneye göre, güçlü Kışbaltası trollerinin lideri, Alterac Vadisi sakinlerine zarar vermek için istediği zaman ortaya çıkar.NEW_LINENEW_LINEKorrak kendini gösterecek olursa, onu yok et ve Alterac Dağları'ndaki Teğmen Haggerdin'e geri dön.",
    ["Progress"] = "Uyarmadı deme asker: Buzkurdu da Korrak'ı avlıyor.",
    ["Completion"] = "Aferin. Korrak'ın ölümüyle tüm dikkatimiz Buzkurdu pisliğini bölgeden temizlemeye odaklanabilir.",
    ["minlevel"] = "51",
    ["questlevel"] = "60"
},

