    ["Completion"] = "Geçmişteki olaylardan çok çekiyoruz. Tahtasaqalı'yı korumaya yardımcı olmak için yaptıkların için teşekkür ederiz.",
    ["minlevel"] = "45",
    ["questlevel"] = "48"
},

