["9266"] = {
    ["Title"] = "Gönül Alma",
    ["Description"] = "",
    ["Objectives"] = "",
    ["Progress"] = "Bize veya arkadaşlarımıza gerçekten kötü bir şey yapmış olmalısın, YOUR_NAME. Her neyse, yeniden gözümüze girmen için sana bir yol sunmak üzere buradayım.NEW_LINENEW_LINEBildiğin gibi, Kışyöresi oldukça soğuk. Diğer şehirlerden gelen bu kadar çok goblin varken, ısınmak için bir yardıma ihtiyacımız var. Bana biraz rün kumaşı ve kömür getir, ben de senin için iyi laf edeyim. Yine de uyarayım, düşmanlarımız bize yardım etmeni pek hoş karşılamayacak.",
    ["Completion"] = "Teşekkür ederim, YOUR_NAME. Güzel kasabamız nezdinde kendini affettirmek için hızlı bir yoldasın.",
    ["minlevel"] = "40",
    ["questlevel"] = "60"
},

["8874"] = {
    ["Title"] = "Ay Festivali",
    ["Description"] = "Yılın o zamanı geldi, YOUR_NAME! Cenarion Çemberi, Azeroth'un tüm sakinlerini Ay Festivali kutlamalarımıza katılmaya davet ediyor. Ay Festivali Habercisi'ni tam bu şehirde, kutsanmış bir ay ışığı halkasıyla işaretlenmiş bir konumda bulacaksın. Sana tatil hakkında daha fazla şey anlatabilir.",
    ["Objectives"] = "Altşehir girişindeki Ay Festivali Habercisi ile konuş. Diğer başkentlerdeki Ay Festivali Habercileri ile de konuşabilirsin.",
    ["Progress"] = "",
    ["Completion"] = "Hoş geldin, YOUR_NAME. Şenliklere katılmak için mi buradasın?",
    ["minlevel"] = "1",
    ["questlevel"] = "60"
},

["9257"] = {
    ["Title"] = "Atiesh, Muhafız'ın Yüce Asası",
    ["Description"] = "Bu son görev hepsinden en zoru olacak, YOUR_NAME. Hem bir Kadim Tanrı hem de Lik Kralı'nın Generali ile yüzleşip onları mağlup ettin, ancak şimdi Sargeras'ın eliyle yüzleşmelisin.NEW_LINENEW_LINEAsayı Stratholme'a götür. Lordaeron'un en yüce şövalyelerinin katledildiği kutsanmış bir toprak parçasını orada bulacaksın. Kirletilmiş asayı kutsal toprağın üzerine yerleştir ve muazzam güçte bir varlığın içinden çıkıp kırılmasına hazırlan... Asayı kontrol eden iblis varlığı mağlup et ve bana geri dön.",
    ["Objectives"] = "Tanaris'teki Zaman Mağaraları'nda bulunan Anachronos, Atiesh, Muhafız'ın Yüce Asası'nı Stratholme'a götürmeni ve Kutsanmış Toprak üzerinde kullanmanı istiyor. Asadan çıkarılan varlığı mağlup et ve ona geri dön.",
    ["Progress"] = "Müdahale etmemeliyim, YOUR_RACE.",
    ["Completion"] = "Bu başarının büyüklüğü azımsanmamalıdır, YOUR_NAME. Çoğu kişinin imkansız olduğunu düşüneceği bir şeyi başardın. Ne yazık ki, bu kaderdi. Asa seçimini yaptı.",
    ["minlevel"] = "60",
    ["questlevel"] = "60"
},

["8796"] = {
    ["Title"] = "İttifak'ın Yardımına İhtiyacı Var!",
    ["Description"] = "Merhaba, beni dinlemeye karar verdiğin için sevindim. İttifak'ın Ahn'Qiraj Savaşı'na hazırlanmak için alabileceği tüm yardıma ihtiyacı var ve bu senin de yardımına ihtiyacımız olduğu anlamına geliyor! Şu anda bile resmi toplayıcılar yaklaşan savaş için gerekli malzemeleri topluyor, ancak senin yardımın olmadan hedeflerimize ulaşamayacağız, YOUR_NAME!NEW_LINENEW_LINESorumlu adam olan Saha Marşalı Snowfall ile konuşmalısın. Ne dersin, YOUR_CLASS? Hayati hazırlıklara yardım edecek misin?",
    ["Objectives"] = "Demirocağı'nın Askeri Bölgesi'ndeki Saha Marşalı Snowfall ile konuş.",
    ["Progress"] = "",
    ["Completion"] = "Selamlar delikanlı! Yaklaşan Ahn'Qiraj Savaşı'nın temelini atmak için desteğini sunmaya gelen senin gibi pek çok İttifak üyesini görmek ne güzel, YOUR_NAME. Buradaki çaba, Silithid'e ve Ahn'Qiraj'ın içinde saklanan kötü efendilerine karşı galip gelmemizi sağlayacak.NEW_LINENEW_LINEArtık burada olduğuna göre, çeşitli toplayıcılarla konuştuğundan ve uygun olduğun malzemeleri toplama konusunda yardımını sunduğundan emin ol.",
