},

["969"] = {
    ["Title"] = "Şans Seninle Olsun",
    ["Description"] = "Ah, sadece sana bakarak anlayabiliyorum -- bir şans muskası yapmak istiyorsun. Mau'ari her zaman bilir!NEW_LINENEW_LINEGüneye doğru. bir kanyon ve som buzdan yapılmış devler bulacaksın. Devler bazen onları taşıyor ama parçaları kanyondan kendin de toplayabilirsin. Bu parçaların güçlü bir yansıtıcı özelliği var.NEW_LINENEW_LINE10 Buzuzağı Parçası getir, şans muskam senin olsun.",
    ["Objectives"] = "Everlook'taki Büyü Doktoru Mau'ari için 10 Buzuzağı Parçası topla.",
    ["Progress"] = "Parçaları getir, sana daha fazlasını anlatayım!",
    ["Completion"] = "Ahh, evet... Şimdi sana muskayı yapacağım. Sen sadece bekle!",
    ["minlevel"] = "55",
    ["questlevel"] = "60"
},

["975"] = {
    ["Title"] = "Mau'ari'nin Zulası",
    ["Description"] = "Şimdi, bu muskayı sana vermeden önce nasıl kullanacağını açıklasam iyi olur.NEW_LINENEW_LINEMuskayı yanında taşırsan, savaştığın yaratıklardan belirli eşyaların düştüğünü göreceksin. Muska yanında yoksa onları bulamazsın. Anladın mı?NEW_LINENEW_LINEBu özel eşyaları isimlerinden tanıyacaksın -- E'ko olarak adlandırılırlar. Bu eşyalardan herhangi birini bulursan, ihtiyar Mau'ari'ye getir, sana yardım etsin.NEW_LINENEW_LINESen muskanı tamir ederken burada bekle.",
    ["Objectives"] = "Şans muskasını almak için bir süre sonra Büyü Doktoru Mau'ari ile tekrar konuş.",
    ["Progress"] = "",
    ["Completion"] = "İşte burada, YOUR_NAME. Unutma, yanında taşıman gerekiyor. Neden Winterspring'e geri dönüp orada neler bulabileceğine bakmıyorsun?",
    ["minlevel"] = "55",
    ["questlevel"] = "60"
},

