["50305"] = {
    ["Title"] = "Daha Yüksek Bahisler",
    ["Description"] = "Şimdi ne var? Ah, yine sensin. Ne yumurtası?NEW_LINENEW_LINEOh, doğru. Kuyruk kırbaçlayanlar. Demek yumurta dışında bir şey pişirmek istiyorsun? Sanırım sana bir şey öğretebilirim.NEW_LINENEW_LINESouthfury Nehrinin nerede bittiğini biliyor musun? Gitmen gereken yer burası. Neden mi? Burada bahisleri yükseltmek niyetindeyim enik! Bana o timsahların etini getir ben de sana onu nasıl düzgün pişireceğini öğreteyim! Onları nehrin her yerinde bulacaksın o yüzden hemen harekete geçsen iyi olur!",
    ["Objectives"] = "Razor Hill'deki Aşçı Torka'ya 8 Timsah Eti getir.",
    ["Progress"] = "Eti aldın mı?",
    ["Completion"] = "Güzel.NEW_LINENEW_LINEOnu pişirmek için zayıf bir girişimde bulunarak ziyan etmeden önce sana bir şey söyleyeyim. Bu etinin hazır olmasıyla ilgili baharat miktarıyla ilgilidir, ateş miktarıyla değil.NEW_LINENEW_LINEPekala, ateş yine de gerekli…",
    ["minlevel"] = "8",
    ["questlevel"] = "10"
},

["807"] = {
    ["Title"] = "[Kullanımdan Kaldırıldı] Durotar Temizliği",
    ["Description"] = "Gözcülerim bazı yaban hayatının iblis lekesi ile enfekte olduğunu bildiriyor. Kardeşlerinin arasında normal canavarlar gibi geziyorlar ama içlerinden kötü bir güç akıyor. Her birinin içinde karanlık büyüyle kavrulmuş bir kalp yanıyor. Bu canavarlar yok edilmeli!NEW_LINENEW_LINEKeşif yaparken böyle bir hayvan bulursan onu öldür ve kavrulmuş kalbini topla. Gezilerin boyunca bulduklarını incelemem için bana getir, ben de onları yok ettireyim.",
    ["Objectives"] = "Razor Hill'deki Orgnil Ruhyarası'na 5 Kavrulmuş Kalp getir.",
    ["Progress"] = "İncelemem için kalpleri bana getir, ben de onları yok ettireyim. Durotar yozlaşmaya teslim olmayacak!",
    ["Completion"] = "Keskin gözünle bu canavarları avlayarak hepimize az hizmet etmedin. Bunları Savaşşefi'nin güvenilir gözlerinin yozlaşmanın nereden kaynaklandığını görmek için çalışacağı Orgrimmar'a göndermesi için bir ulak çağırdım bile.",
    ["minlevel"] = "4",
    ["questlevel"] = "10"
},

["810"] = {
    ["Title"] = "Hayatta Kalmak İçin Çalış",
    ["Description"] = "Bu toprakların ne kadar tehlikeli olabileceğini öğrensen iyi edersin, YOUR_CLASS. Buradaki yaban hayatı derslerini dinleyecek kadar bilge olursak bize inanılmaz şeyler öğretebilir.NEW_LINENEW_LINESkorpidler Durotar'da hayatta kalmanın mükemmel bir örneğidir. Toprak sertleşip daha acımasız hale gelse de sertleşmiş kabukları onları acımasız güneşten ve avcıların ölümcül silahlarından korur. Şu anda çevreye hakim oldukları için onların bazı güçlerini almak akıllıca olabilir.NEW_LINENEW_LINEBana Çangırdayan Skorpidler'den 6 Küçük Skorpid Kabuğu getir, YOUR_NAME, ben de ödülünle ilgileneyim.",
    ["Objectives"] = "Sen'jin Köyü'ndeki Kor'ghan'a 6 Küçük Skorpid Kabuğu getir.",
    ["Progress"] = "Kabuklara sahip misin?",
    ["Completion"] = "Bu kabuklar avcılarımızı kavurucu sıcaktan ve savanın tehlikelerinden korumak için zırh plakaları yapmaya yarayacak. Teşekkür ederim, YOUR_NAME.",
    ["minlevel"] = "4",
    ["questlevel"] = "5"
},

["811"] = {
    ["Title"] = "Birlik Güçtür",
    ["Description"] = "Skorpidlerin diğer özelliklerinden biri de şiddetli sadakatleridir. Kişisel riski göze alarak birbirlerini koruyacaklardır - muhtemelen ilk avın sırasında bu davranışı zaten görmüşsündür. Bu dersi dikkate alıp kendine uyarlasan iyi edersin: bir olarak daha güçlüyüz; bölündüğümüzde zayıfız.NEW_LINENEW_LINEZırhlı Skorpidler'den bana 8 Büyük Skorpid Kabuğu getir sana başka bir ödül vereyim.",
    ["Objectives"] = "Gölge Yarığı'ndaki Kor'ghan'a 8 Büyük Skorpid Kabuğu getir.",
    ["Progress"] = "Onlara tek başına saldırıyorsan skorpidleri hafife almamaya dikkat et.",
    ["Completion"] = "Yeni evimizin gücüyle av gruplarını daha da zırhlandıracağız. Kendini toprakların hikmetine açık tut, YOUR_NAME.",
